@Composable
fun InfoDialog(onDismiss: () -> Unit) {
    val resolvedSections = infoSections.map {
        ResolvedInfoSection(title = stringResource(it.titleRes), body = stringResource(it.bodyRes))
    }
    var query by remember { mutableStateOf("") }
    val matches = if (query.isBlank()) {
        resolvedSections
    } else {
        resolvedSections.filter {
            it.title.contains(query, ignoreCase = true) || it.body.contains(query, ignoreCase = true)
        }
    }

    GoblinAlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Text(
                stringResource(R.string.info_dialog_title),
                fontWeight = FontWeight.ExtraBold,
                color = MaterialTheme.colorScheme.primary
            )
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                OutlinedTextField(
                    value = query,
                    onValueChange = { query = it },
                    modifier = Modifier.fillMaxWidth().testTag("info_search_field"),
                    placeholder = { Text(stringResource(R.string.info_search_placeholder), fontSize = 13.sp) },
                    leadingIcon = { Icon(Icons.Filled.Search, contentDescription = null) },
                    trailingIcon = {
                        if (query.isNotEmpty()) {
                            IconButton(onClick = { query = "" }, modifier = Modifier.testTag("info_search_clear_button")) {
                                Icon(Icons.Filled.Clear, contentDescription = stringResource(R.string.clear_search_content_description))
                            }
                        }
                    },
                    singleLine = true
                )

                Column(
                    modifier = Modifier.verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    if (matches.isEmpty()) {
                        Text(
                            text = stringResource(R.string.no_topics_match, query),
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                            modifier = Modifier.testTag("info_search_no_results")
                        )
                    }
                    matches.forEachIndexed { index, section ->
                        SettingsSectionHeader(section.title)
                        Text(
                            text = section.body,
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                        )
                        if (index != matches.lastIndex) {
                            HorizontalDivider(color = MaterialTheme.colorScheme.surfaceVariant)
                        }
                    }
                }
            }
        },
        confirmButton = {
            TextButton(onClick = onDismiss, modifier = Modifier.testTag("info_dialog_dismiss_button")) {
                Text(stringResource(R.string.action_got_it), fontWeight = FontWeight.Bold)
            }
        }
    )
}
